/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// Get Source transaction tax item group
/// </summary>
/// <returns>TaxItemGroup of source tramsactions</returns>
protected TaxItemGroup getTaxItemGroup()
{
    TaxItemGroup taxItemGroup = next getTaxItemGroup();

    if (rebateTransactionType == TAMRebateTransactionType::Rebate && this.getRebatePosting().METFollowTransItemGSTGroup == NoYes::Yes)
    {
        taxItemGroup = this.parmItemSalesTaxGroup();

    }

    // CB705_VendorRebatePosting
    // Have to set the default dimension for the vendor line and from the vendor rebate type here
    // after ledgerJournalEngine.accountModified(ledgerJournalTrans) is called as it will default the dimension from the vendor account
    if (ledgerJournalTrans.accountType == LedgerJournalACType::Vend
    &&  this.METApplyConsolidationByVendorRebateType())
    {
        METVendorRebateType vendRebatetype = METVendorRebateType::find(rebateDateTrans.METVendRebateTypeId);
        if (vendRebatetype.DefaultDimension)
        {
            ledgerJournalTrans.DefaultDimension = vendRebatetype.DefaultDimension;
        }
    }

    return taxItemGroup;
}

/// <summary>
/// CB705_VendorRebatePosting
/// Make sure the createDocument.LedgerJournalTable is reset everytime processing a new TAMRebateDateTrans as
/// they are grouped by rebate type to make sure a new vendor invoice journal header is created.
/// </summary>
public void METResetLedgerJournalTable()
{
    ledgerJournalTable = null;
}

/// <summary>
/// CB705_VendorRebatePosting
/// Set invoiceId from the new number sequence linked to vendor rebate type
/// In the standard method shouldReuseInvoice will return true and skip the if statement
/// </summary>
/// <returns>Invoice number</returns>
public InvoiceId getJournalInvoiceId()
{
    TAMRebateParameters rebateParameters = TAMRebateParameters::find();

    if (this.METApplyConsolidationByVendorRebateType()
    &&  rebateParameters.METVendInvoiceNumByVendRebType
    &&  !this.parmInvoiceId())
    {
        METNumberSequenceId numberSequenceId = METVendorRebateType::find(rebateDateTrans.METVendRebateTypeId).NumberSequenceId;

        if (numberSequenceId)
        {
            Num localInvoiceId = NumberSeq::newGetNumFromId(numberSequenceId).num();
            this.parmInvoiceId(localInvoiceId);
        }
    }

    return next getJournalInvoiceId();
}

/// <summary>
/// CB705_VendorRebatePosting
/// get the journal name id based on the vendor rebate type
/// </summary>
/// <returns><c>LedgerJournalNameId</c></returns>
protected LedgerJournalNameId getJournalNameId()
{
    LedgerJournalNameId journalNameId = next getJournalNameId();

    if (this.METApplyConsolidationByVendorRebateType())
    {
        METVendorRebateType vendorRebateType = METVendorRebateType::find(rebateDateTrans.METVendRebateTypeId);

        // This journal name will be used to generate consolidated rebate invoice against the vendor for all deal lines with corresponding rebate type.
        if (vendorRebateType && vendorRebateType.JournalNameId)
        {
            journalNameId = vendorRebateType.JournalNameId;
        }
    }

    return journalNameId;
}

/// <summary>
/// CB705_VendorRebatePosting
/// Method to determine if the consolidation by vendor rebate type should be applied.
/// </summary>
/// <returns>True if consolidation should be applied; otherwise, false.</returns>
private boolean METApplyConsolidationByVendorRebateType()
{
    return (TAMRebateParameters::find().METProcessVendRebateBasedVendRebType
        &&  rebateTransactionType == TAMRebateTransactionType::Rebate
        &&  METRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend
        &&  METRebateDeal.RebateType == TAMRebateType::Rebate
        &&  METRebateDeal.RebateReconciliation == TAMRebateReconciliation::Line
        &&  METRebateDeal.METInvoiceConsolidationByRebateType == NoYes::Yes
        &&  rebateDateTrans.METVendRebateTypeId);
}

/// <summary>
/// Trigger the journal line description after it's created
/// </summary>
/// <param name = "_amount">Amount</param>
/// <param name = "_dimension">Dimension</param>
/// <param name = "_groupByDimension">Group by dimension</param>
protected void createLedgerJournalTrans(Amount _amount, DimensionDefault _dimension, boolean _groupByDimension)
{
    next createLedgerJournalTrans(_amount, _dimension, _groupByDimension);

    // Can only update the description field after the line is inserted/updated
    // as txt field is set from rebateDocumentNotes in insertLedgerJournalTrans (private)
    // no extension point between the field being set on the ledgerJournalTrans.write() or ledgerJournalTrans.insert()
    this.metUpdateLedgerJournalTrans(_dimension);
}

/// <summary>
/// /// Trigger the journal line description after it's created
/// </summary>
/// <param name = "_amount">Amount</param>
/// <param name = "_dimension">Dimension</param>
protected void createLedgerJournalTransInvoice(Amount _amount, DimensionDefault _dimension)
{
    next createLedgerJournalTransInvoice(_amount, _dimension);

    // Can only update the description field after the line is inserted/updated
    // as txt field is set from rebateDocumentNotes in insertLedgerJournalTrans (private)
    // no extension point between the field being set on the ledgerJournalTrans.write() or ledgerJournalTrans.insert()
    this.metUpdateLedgerJournalTrans(_dimension);
}

private LedgerDimensionAccount metGetRebateClearingAccount(DimensionDefault _dimension, LedgerJournalTrans _ledgerJournalTrans)
{
    TAMRebateTable rebateTable;

    select firstonly RebateCompanyId 
        from rebateTable 
        where rebateTable.RebateDeal == METRebateDeal.RecId 
        && rebateTable.RebatePostingId == this.parmMetRebatePostingId();

    TAMRebatePosting rebatePostingLoc = TAMRebatePosting::find(this.parmMetRebatePostingId(), ModuleInventCustVend::Vend);
    TAMRebatePostingCompany rebatePostingCompanyLoc = TAMRebatePostingCompany::findPostingCompany(rebatePostingLoc.RecId, rebateTable.RebateCompanyId);
    TAMRebatePostingAccount rebatePostingAccount = TAMRebatePostingAccount::newFromRebatePosting(
        rebatePostingLoc,
        rebateTransactionType,
        rebatePostingCompanyLoc,
        TAMRebateReconciliation::Line);

    if (_ledgerJournalTrans.AccountType == LedgerJournalACType::Ledger)
    {
        return LedgerDimensionFacade::serviceCreateLedgerDimension(
                ledgerJournalTrans.getLedgerDimensionForLedgerType(rebatePostingAccount.offsetLedgerDimension(), _ledgerJournalTrans.Company),
                _dimension);
    }
    else
    {
        return rebatePostingAccount.offsetLedgerDimension();
    }
}

/// <summary>
/// Method to override the journal line description field from the vendor rebate type description
/// </summary>
protected void metUpdateLedgerJournalTrans(DimensionDefault _dimension)
{
    LedgerJournalTrans ledgerJournalTransLocal;
    PaymTerm                    paymTerm;

    ledgerJournalTransLocal = LedgerJournalTrans::findRecId(ledgerJournalTrans.recId, true);
    boolean isUpdated = false;

    // to exclude provision
    if (ledgerJournalTransLocal && rebateTransactionType == TAMRebateTransactionType::Rebate)
    {
        METVendorRebateType vendorRebateType = METVendorRebateType::find(rebateDateTrans.METVendRebateTypeId);

        // only update the journal line description if the vendor rebate type has a description
        if (vendorRebateType.Description)
        {
            ledgerJournalTransLocal.Txt = vendorRebateType.Description;
            isUpdated = true;
        }

    }

    if (ledgerJournalTransLocal && ledgerJournalTransLocal.AccountType == LedgerJournalACType::Vend)
    {

        VendAccount vendAccount = ledgerJournalTransLocal.parmAccount();
        if (vendAccount)
        {
            PaymTermId creditPaymTermId = METVendTable::getCreditPaymId(vendAccount);
            if (creditPaymTermId)
            {
                ledgerJournalTransLocal.Payment = creditPaymTermId;
                ledgerJournalTransLocal.modifiedField(fieldNum(LedgerJournalTrans, Payment));

                paymTerm = PaymTerm::find(ledgerJournalTransLocal.Payment);

                ledgerJournalTransLocal.Due = paymTerm.due(ledgerJournalTransLocal.TransDate, paymTerm.PaymDayId);

                isUpdated = true;
            }
        }
    }

    // Bug 294181: CB705- For Vendor rebate, journal entries are not correct when Payback to vendor is marked as TRUE
    // moved and fixed the logic here after the journal record is inserted as createDocumentLine can call createLedgerJournalTransInvoice and createLedgerJournalTrans
    if (rebateDateTrans.TAMRebateTable().METEnableVendorPayBack)
    {
        if (ledgerJournalTransLocal)
        {
            AmountCurCredit credit = ledgerJournalTransLocal.AmountCurCredit;
            AmountCurDebit  debit  = ledgerJournalTransLocal.AmountCurDebit;

            ledgerJournalTransLocal.AmountCurCredit = debit;
            ledgerJournalTransLocal.AmountCurDebit = credit;
            isUpdated = true;
        }
    }

    if(this.METApplyConsolidationByVendorRebateType() && this.parmMetRebatePostingId() && ledgerJournalTransLocal.AccountType == LedgerJournalACType::Ledger)
    {
        ledgerJournalTransLocal.LedgerDimension = this.metGetRebateClearingAccount(_dimension, ledgerJournalTransLocal);
        isUpdated = true;
    }

    if (isUpdated)
    {
        ledgerJournalTransLocal.update();
    }
}

/// <summary>
/// Bug 344875: [MS] E2E - CB201 - Write Offs were not posted as part of the weekend Batch Job. MS SR# - 2603110030000116
/// MS temp fix
/// </summary>
public void postDocuments()
{
    // Remove empty journal headers before posting
    List cleanedList = new List(Types::Record);
    ListEnumerator enumerator = headerList.getEnumerator();

    while (enumerator.moveNext())
    {
        LedgerJournalTable journalTable = enumerator.current() as LedgerJournalTable;

        if (journalTable)
        {
            LedgerJournalTrans journalTrans;
            select firstOnly RecId from journalTrans
                   where journalTrans.JournalNum == journalTable.JournalNum;

            if (journalTrans.RecId)
            {
                cleanedList.addEnd(journalTable);
            }
            else
            {
                journalTable.delete();
            }
        }
    }

    headerList = cleanedList;

    next postDocuments();
}
